	Declare(&Globalenv, &Declaration{
		Name: "parallelN_mut",

		Fn: func(a ...Scmer) Scmer {
			n := int(a[0].Int())
			if n < 0 {
				n = 0
			}
			fn := a[1]
			needsSerializedCall := fn.GetTag() == tagFunc || fn.GetTag() == tagFuncEnv
			var fnMu sync.Mutex
			callFn := func(i int) Scmer {
				if needsSerializedCall {
					fnMu.Lock()
					defer fnMu.Unlock()
				}
				return Apply(fn, NewInt(int64(i)))
			}
			workers := runtime.NumCPU()
			if workers < 1 {
				workers = 1
			}
			if workers > n {
				workers = n
			}
			if len(a) < 3 || a[2].IsNil() {
				jobs := make(chan int, workers)
				errs := make(chan any, workers)
				var wg sync.WaitGroup
				for w := 0; w < workers; w++ {
					wg.Add(1)
					go func() {
						defer wg.Done()
						for i := range jobs {
							func() {
								defer func() {
									if r := recover(); r != nil {
										errs <- r
									}
								}()
								callFn(i)
							}()
						}
					}()
				}
				for i := 0; i < n; i++ {
					jobs <- i
				}
				close(jobs)
				wg.Wait()
				close(errs)
				for err := range errs {
					if err != nil {
						panic(err)
					}
				}
				return NewNil()
			}
			result := asSlice(a[2], "parallelN_mut target")
			if len(result) < n {
				panic("parallelN_mut target too small")
			}
			result = result[:n]
			jobs := make(chan int, workers)
			errs := make(chan any, workers)
			var wg sync.WaitGroup
			for w := 0; w < workers; w++ {
				wg.Add(1)
				go func() {
					defer wg.Done()
					for i := range jobs {
						func() {
							defer func() {
								if r := recover(); r != nil {
									errs <- r
								}
							}()
							result[i] = callFn(i)
						}()
					}
				}()
			}
			for i := 0; i < n; i++ {
				jobs <- i
			}
			close(jobs)
			wg.Wait()
			close(errs)
			for err := range errs {
				if err != nil {
					panic(err)
				}
			}
			return NewSlice(result)
		},
		Type: &TypeDescriptor{Kind: "func", Description: "in-place parallelN variant (optimizer-only)",
			Params: []*TypeDescriptor{
				{Kind: "number", Label: "n", Description: "number of elements to produce"},
				{Kind: "func", Label: "fn", Description: "map function applied to each index in parallel", Params: []*TypeDescriptor{{Kind: "int", Label: "index"}}, Return: &TypeDescriptor{Kind: "any"}},
				{Kind: "list", Label: "target", Description: "(optional) preallocated target list", NoEscape: true, Optional: true},
			},
			Return:    &TypeDescriptor{Kind: "list"},
			Const:     true,
			Forbidden: true,

			JITEmit: func(ctx *JITContext, _ []Scmer, args []JITValueDesc, result JITValueDesc) JITValueDesc {
				return jitEmitGoVariadicCallFromDescs(ctx, declarations["parallelN_mut"].Fn, args, result)
			},
			JITVirtualArgs: true,
		},
	})
